test('acknowledged release', async () => {
  const h: any = await createHost();
  await h.acquire('c0'); await h.deliverAll();
  assert.deepEqual(await h.release('c0'), { ok: true });
  assert.equal((await h.client('c0')).status, 'releasing');
  assert.equal((await h.acquire('c0')).ok, false);
  assert.equal((await h.write('c0')).ok, false);
  assert.equal((await h.release('c0')).ok, false);
  await h.deliver((await find(h, 'Release')).id);
  const r = await find(h, 'Released');
  assert.equal(r.to, 'c0'); assert.equal(r.from, 'lease'); assert.deepEqual(r.data, {});
  assert.equal((await h.lease()).holder, null);
  assert.equal((await h.client('c0')).status, 'releasing');
  await h.deliverAll();
  assert.deepEqual(await h.client('c0'), { status: 'idle', token: 1, writing: false });
});

test('releasing client ignores Revoked, ignored release still answered', async () => {
  const h: any = await createHost();
  await h.acquire('c0'); await h.deliverAll();
  await h.release('c0');
  await h.expire();
  await h.deliver((await find(h, 'Revoked')).id);
  assert.equal((await h.client('c0')).status, 'releasing');
  await h.deliver((await find(h, 'Release')).id);
  assert.notEqual(await find(h, 'Released'), undefined);
  await h.deliverAll();
  assert.deepEqual(await h.client('c0'), { status: 'idle', token: 1, writing: false });
  assert.deepEqual(await h.lease(), { holder: null, token: 1, writes: 0 });
  await h.acquire('c0'); await h.deliverAll();
  assert.deepEqual(await h.client('c0'), { status: 'holding', token: 2, writing: false });
});

