import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const find = async (h: any, action: string, to?: string) =>
  (await h.inFlight()).find((m: any) => m.action === action && (to === undefined || m.to === to));

test('initial state and unknown ids', async () => {
  const h: any = await createHost();
  assert.deepEqual(await h.lease(), { holder: null, token: 0, writes: 0 });
  assert.deepEqual(await h.client('c0'), { status: 'idle', token: 0, writing: false });
  assert.equal(await h.client('lease'), null);
  assert.equal(await h.client('c9'), null);
  assert.equal((await h.acquire('c9')).ok, false);
  assert.equal((await h.acquire('lease')).ok, false);
  assert.equal((await h.expire()).ok, false);
  assert.equal((await h.release('c0')).ok, false);
  assert.equal((await h.write('c0')).ok, false);
  await h.__dispose();
});

test('acquire, write, release, messages', async () => {
  const h: any = await createHost();
  assert.deepEqual(await h.acquire('c0'), { ok: true });
  assert.equal((await h.acquire('c0')).ok, false);
  const m = await h.inFlight();
  assert.equal(m.length, 1);
  assert.equal(m[0].from, 'c0'); assert.equal(m[0].to, 'lease'); assert.equal(m[0].action, 'Acquire');
  assert.deepEqual(m[0].data, { from: 'c0' });
  await h.deliverAll();
  assert.deepEqual(await h.client('c0'), { status: 'holding', token: 1, writing: false });
  assert.deepEqual(await h.lease(), { holder: 'c0', token: 1, writes: 0 });
  assert.deepEqual(await h.write('c0'), { ok: true });
  assert.equal((await h.write('c0')).ok, false);
  assert.deepEqual((await find(h, 'Write')).data, { from: 'c0', token: 1 });
  await h.deliverAll();
  assert.deepEqual(await h.lease(), { holder: 'c0', token: 1, writes: 1 });
  assert.equal((await h.client('c0')).writing, false);
  await h.acquire('c1');
  await h.deliverAll();
  assert.equal((await h.client('c1')).status, 'idle');
  assert.deepEqual(await h.release('c0'), { ok: true });
  assert.deepEqual((await find(h, 'Release')).data, { from: 'c0', token: 1 });
  await h.deliverAll();
  assert.equal((await h.lease()).holder, null);
  await h.acquire('c1'); await h.deliverAll();
  assert.deepEqual(await h.client('c1'), { status: 'holding', token: 2, writing: false });
  await h.release('c1'); await h.deliverAll();
  await h.acquire('c0'); await h.deliverAll();
  assert.equal((await h.client('c0')).status, 'idle');
  assert.deepEqual(await h.lease(), { holder: null, token: 2, writes: 1 });
  await h.__dispose();
});

test('expire and stale write is refused', async () => {
  const h: any = await createHost();
  await h.acquire('c0'); await h.deliverAll();
  await h.write('c0');
  assert.deepEqual(await h.expire(), { ok: true });
  assert.deepEqual((await find(h, 'Revoked')).data, { token: 1 });
  await h.deliver((await find(h, 'Write')).id);
  assert.equal((await find(h, 'WriteRefused')) !== undefined, true);
  await h.deliverAll();
  assert.deepEqual(await h.client('c0'), { status: 'idle', token: 1, writing: false });
  assert.deepEqual(await h.lease(), { holder: null, token: 1, writes: 0 });
});

test('one write per grant', async () => {
  const h: any = await createHost();
